import{_ as i,o as a,c as n,ah as l}from"./chunks/framework.CmTHHbTK.js";const r="/projects/AiNovaPro/en/latest/assets/image2.Cox1X-B7.webp",t="/projects/AiNovaPro/en/latest/assets/image3.xlXTUpM_.webp",c="/projects/AiNovaPro/en/latest/assets/image4.a5w3ZVTV.webp",h="/projects/AiNovaPro/en/latest/assets/image5.CftKazMD.webp",o="/projects/AiNovaPro/en/latest/assets/image6.Dc7QzX6p.webp",d="/projects/AiNovaPro/en/latest/assets/image7.CbXEHiL5.webp",p="/projects/AiNovaPro/en/latest/assets/image8.B9Y2TCls.webp",g="data:image/png;base64,",m="/projects/AiNovaPro/en/latest/assets/image10.D3guFbqf.webp",s="/projects/AiNovaPro/en/latest/assets/image11.DQQ6NFPO.webp",u="/projects/AiNovaPro/en/latest/assets/image13.wJd9gRg_.webp",v="/projects/AiNovaPro/en/latest/assets/image14.CBreb4Xa.webp",y="/projects/AiNovaPro/en/latest/assets/image15.DMBobO6Z.webp",b="/projects/AiNovaPro/en/latest/assets/image16.DJp7AcIx.webp",w="/projects/AiNovaPro/en/latest/assets/image17.CAvYjM62.webp",f="/projects/AiNovaPro/en/latest/assets/image18.CCKEUDrv.webp",k="/projects/AiNovaPro/en/latest/assets/image19.CGLKNvdX.webp",_="/projects/AiNovaPro/en/latest/assets/image2.bRFzUb2t.webp",x="/projects/AiNovaPro/en/latest/assets/image3.C0K57vrR.webp",C="/projects/AiNovaPro/en/latest/assets/image4.xgkdhrAl.webp",P="/projects/AiNovaPro/en/latest/assets/image5.CmCjHrY-.webp",A="/projects/AiNovaPro/en/latest/assets/image6.-fWJ1ekj.webp",j=JSON.parse('{"title":"13. Group Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/13_Group_Control.md","filePath":"docs/13_Group_Control.md"}'),z={name:"docs/13_Group_Control.md"};function N(E,e,q,T,O,L){return a(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="_13-group-control" tabindex="-1">13. Group Control <a class="header-anchor" href="#_13-group-control" aria-label="Permalink to &quot;13. Group Control&quot;">​</a></h1><h2 id="_13-1-host-slave-and-environment-variable-configuration" tabindex="-1">13.1 Host-Slave and Environment Variable Configuration <a class="header-anchor" href="#_13-1-host-slave-and-environment-variable-configuration" aria-label="Permalink to &quot;13.1 Host-Slave and Environment Variable Configuration&quot;">​</a></h2><h3 id="_13-1-1-preparation" tabindex="-1">13.1.1 Preparation <a class="header-anchor" href="#_13-1-1-preparation" aria-label="Permalink to &quot;13.1.1 Preparation&quot;">​</a></h3><ol><li><p>In this lesson, two robot units will be used as an example, please prepare at least two LanderPi.</p></li><li><p>To set up the development environment, please follow the instructions in <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#development-environment-setup-and-configuration" target="_blank" rel="noreferrer">1.4 Development Environment Setup and Configuration</a> in the user manual to download and install the remote connection tool VNC.</p></li></ol><h3 id="_13-1-2-working-principle" tabindex="-1">13.1.2 Working Principle <a class="header-anchor" href="#_13-1-2-working-principle" aria-label="Permalink to &quot;13.1.2 Working Principle&quot;">​</a></h3><p>By configuring the host and slave on the same network and using separate namespaces, the broadcast program sends speed commands to the slaves, achieving synchronized control. In this case, connect to the Raspberry Pi&#39;s hotspot to demonstrate the process.</p><p id="anchor_13_1_3"></p><h3 id="_13-1-3-network-configuration" tabindex="-1">13.1.3 Network Configuration <a class="header-anchor" href="#_13-1-3-network-configuration" aria-label="Permalink to &quot;13.1.3 Network Configuration&quot;">​</a></h3><ul><li><strong>Configure Host Network</strong></li></ul><ol><li>First, select one LanderPi as the host, power it on, and remotely connect to its system desktop.</li></ol><ol start="2"><li>Open the command-line terminal and enter the following command to navigate to the directory where the file is located.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd wifi_manager</span></span></code></pre></div><img loading="lazy" height="205" width="748" src="'+r+'" style="width:500px;" class="common_img"><ol start="3"><li>Enter the following command to open the Wi-Fi configuration file using the Vim editor.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim wifi_conf.py</span></span></code></pre></div><img loading="lazy" height="181" width="749" src="'+t+'" style="width:500px;" class="common_img"><ol start="4"><li>Press the <strong>i</strong> key on your keyboard to enter edit mode. To modify the host hotspot password, locate the two lines of code highlighted in the figure below.</li></ol><img loading="lazy" height="423" width="749" src="'+c+'" style="width:500px;" class="common_img"><ol start="5"><li>After successfully making the modifications, press <strong>Esc</strong> to exit edit mode. Then type the following code to save and exit.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><img loading="lazy" height="423" width="748" src="'+h+'" style="width:500px;" class="common_img"><ol start="6"><li>Enter the command to reboot the host.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo reboot</span></span></code></pre></div><img loading="lazy" height="181" width="749" src="'+o+'" style="width:500px;" class="common_img"><ol start="7"><li>After the host has rebooted, reconnect to its Wi-Fi using the password <strong>hiwonder</strong>.</li></ol><ul><li><strong>Configure the Slave Device Network</strong></li></ul><ol><li><p>Power on the slave device and remotely connect to its system desktop.</p></li><li><p>Open the command-line terminal and enter the following command to navigate to the directory where the file is located.</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd wifi_manager</span></span></code></pre></div><img loading="lazy" height="181" width="749" src="'+t+'" style="width:500px;" class="common_img"><p>3） Enter the following command to open the Wi-Fi configuration file using the Vim editor.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim wifi_conf.py</span></span></code></pre></div><img loading="lazy" height="181" width="749" src="'+t+'" style="width:500px;" class="common_img"><p>4）Press the <strong>i</strong> key on the keyboard to enter edit mode. Then, modify the Wi-Fi name and password as shown in the figure, and locate the three highlighted lines.</p><img loading="lazy" height="424" width="748" src="'+d+'" style="width:500px;" class="common_img"><p>Set the slave device&#39;s network mode to <code>2</code>, which corresponds to LAN mode. <code>HW-123</code> and <code>hiwonder</code> are the host Wi-Fi name and password set in <a href="#anchor_13_1_3">Configure Host Network</a>.</p><p>6）After successfully making the modifications, press <strong>Esc</strong> to exit edit mode. Then type the following code to save and exit.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><img loading="lazy" height="422" width="749" src="'+p+'" style="width:500px;" class="common_img"><p>7）Enter the command to reboot the device. Donot skip this step!</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo reboot</span></span></code></pre></div><img loading="lazy" height="181" width="749" src="'+o+'" style="width:500px;" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>When LanderPi is powered on in LAN mode, it will automatically search for the preset network. During this process, LED2 on the Raspberry Pi expansion board will flash rapidly, indicating that the network search is in progress. If the target network is not found after three consecutive search attempts, LanderPi automatically switches to direct connection mode, and LED2 will flash slowly.</strong></p><p><strong>If LanderPi fails to find the target network in LAN mode and switches to direct connection mode, the wifi_conf.py file will not be modified and will retain the LAN configuration on the next startup.</strong></p><p><strong>Before setting the slave device to LAN mode, ensure that the host is powered on and its network configuration is complete, so that the slave can detect the host&#39;s hotspot. Otherwise, if the slave device cannot find the host hotspot within a certain period after powering on, it may automatically switch to direct connection mode, resulting in the inability to establish a network connection between the master and slave devices.</strong></p></div><p id="anchor_13_1_4"></p><h3 id="_13-1-4-configure-environment-variables" tabindex="-1">13.1.4 Configure Environment Variables <a class="header-anchor" href="#_13-1-4-configure-environment-variables" aria-label="Permalink to &quot;13.1.4 Configure Environment Variables&quot;">​</a></h3><ul><li><strong>Configure Host Environment Variables</strong></li></ul><ol><li><p>Select a LanderPi as the host and power it on. Connect to the Raspberry Pi desktop remotely via VNC.</p></li><li><p>Click <img loading="lazy" height="29" width="31" src="'+g+'" style="width:30px;"> in the top-left corner of the desktop to open the Terminator terminal.</p></li><li><p>Ensure that a USB wireless controller receiver is connected to the host.</p></li></ol><img loading="lazy" height="535" width="823" src="'+m+'" style="width:500px;" class="common_img"><ol start="4"><li>Enter the command to disable auto-start mode and press <strong>Enter</strong>.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div><img loading="lazy" height="363" width="823" src="'+s+'" style="width:500px;" class="common_img"><ol start="5"><li>Enter the command to open .typerc and set up the host environment variables.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim /home/ubuntu/ros2_ws/.typerc</span></span></code></pre></div><ol start="6"><li>Press the <strong>i</strong> key on the keyboard to enter edit mode, and enable the host-slave settings, setting the host to <code>robot_1</code>.</li></ol><img loading="lazy" height="536" width="824" src="'+u+'" style="width:500px;" class="common_img"><ol start="7"><li>After making the changes, press <strong>Esc</strong> and type the command to save and exit.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><img loading="lazy" height="182" width="825" src="'+v+'" style="width:500px;" class="common_img"><ol start="8"><li>Then enter the following command to complete the host setup.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source ~/.zshrc</span></span></code></pre></div><img loading="lazy" height="287" width="824" src="'+y+'" style="width:500px;" class="common_img"><ul><li><strong>Configure Slave Environment Variables</strong></li></ul><ol><li>Open the mobile app and connect to the host&#39;s Wi-Fi. Then search for the robot&#39;s icon. Long-press the icon to display the slave&#39;s IP address. If you want to use this IP, you can refer to <a href="https://wiki.hiwonder.com/projects/LeRobot/en/latest/docs/1_LanderPi_User_Manual.html#anchor_1_4_2_2" target="_blank" rel="noreferrer">LAN Mode Connection (Optional)</a> in the user manual.</li></ol><img loading="lazy" height="570" width="1267" src="'+b+'" style="width:500px;" class="common_img"><img loading="lazy" height="566" width="1267" src="'+w+'" style="width:500px;" class="common_img"><ol start="2"><li>After obtaining the IP, please refer to the section <a href="#anchor_13_1_4">Configure Host Environment Variables</a> for details. First, disable the auto-start service, open the <strong>.typerc</strong> file, and set the slave device&#39;s environment variable HOST to <code>robot_2</code>. After making the changes, save and exit the file. Finally, enter the command <code>source ~/.zshrc</code> to refresh the environment variables.</li></ol><img loading="lazy" height="363" width="823" src="'+s+'" style="width:500px;" class="common_img"><img loading="lazy" height="536" width="823" src="'+f+'" style="width:500px;" class="common_img"><img loading="lazy" height="286" width="822" src="'+k+'" style="width:500px;" class="common_img"><h2 id="_13-2-group-control-startup-and-operation" tabindex="-1">13.2 Group Control Startup and Operation <a class="header-anchor" href="#_13-2-group-control-startup-and-operation" aria-label="Permalink to &quot;13.2 Group Control Startup and Operation&quot;">​</a></h2><h3 id="_13-2-1-synchronize-time" tabindex="-1">13.2.1 Synchronize Time <a class="header-anchor" href="#_13-2-1-synchronize-time" aria-label="Permalink to &quot;13.2.1 Synchronize Time&quot;">​</a></h3><ol><li>On the host device, open the terminal and enter the following command to check the time:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>date</span></span></code></pre></div><img loading="lazy" height="40" width="706" src="'+_+'" style="width:500px;" class="common_img"><ol start="2"><li>On the slave device, open the terminal and enter the following command to synchronize the system time.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The time on the slave device must match the time displayed on the host device.</strong></p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo date -s &quot;2025-8-20 10:50:03&quot;</span></span></code></pre></div><img loading="lazy" height="43" width="702" src="'+x+`" style="width:500px;" class="common_img"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>If noticeable desynchronization occurs between the host and slave devices during joystick operation, it is likely caused by inconsistent system times. In this case, you can return to the previous step and resynchronize the time.</strong></p></li><li><p><strong>When using the <code>date</code> command to synchronize the host&#39;s time with the slave device, the process takes a certain amount of time. Therefore, by the time the update is applied on the slave, the host&#39;s current time may have already moved forward slightly. Since this process may introduce some errors, to avoid them, after obtaining the host&#39;s time, you should manually track the elapsed seconds using a stopwatch or other tools. The time entered on the slave device should then be the host&#39;s time plus the recorded elapsed seconds.</strong></p></li><li><p><strong>After synchronizing the time between the host and slave devices, enter the <code>date</code> command on each device&#39;s command line. Make sure both commands are executed within a short interval. Check the time on both devices—if the difference is minimal, the synchronization is considered successful.</strong></p></li></ul></div><h3 id="_13-2-2-execute-the-program" tabindex="-1">13.2.2 Execute the Program <a class="header-anchor" href="#_13-2-2-execute-the-program" aria-label="Permalink to &quot;13.2.2 Execute the Program&quot;">​</a></h3><ol><li>On the host, open three terminals and enter the following commands in each terminal to execute the respective programs.</li></ol><p><code>joy_node</code>: Start the node for wireless controller.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch large_models llm_control_move.launch.py</span></span>
<span class="line"><span></span></span>
<span class="line"><span>python3 ros2_ws/src/multi/launch/joystick_control_multi.py</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ros2 run joy joy_node</span></span></code></pre></div><img loading="lazy" height="56" width="690" src="`+C+'" style="width:500px;" class="common_img"><img loading="lazy" height="59" width="769" src="'+P+'" style="width:500px;" class="common_img"><img loading="lazy" height="47" width="580" src="'+A+'" style="width:500px;" class="common_img"><p><code>multi_controller.launch.py</code>：Chassis control.</p><p><code>joystick_control_multi.py</code>：Joystick control.</p><ol start="2"><li>On the slave device, enter the following commands to execute the programs.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch multi multi_controller.launch.py</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Each time you power on the devices and want to use the group control mode, you must first disable the auto-start service on both the host and slave devices and synchronize the system time.</strong></p></div><h3 id="_13-2-3-group-control-operation" tabindex="-1">13.2.3 Group Control Operation <a class="header-anchor" href="#_13-2-3-group-control-operation" aria-label="Permalink to &quot;13.2.3 Group Control Operation&quot;">​</a></h3><ol><li><p>Push the wireless controller power switch to the <strong>ON</strong> position. You will see the red and green LED indicators on the wireless controller start flashing simultaneously.</p></li><li><p>Wait a few seconds for the robot and wireless controller to pair automatically. Once pairing is successful, the green LED will remain solid while the red LED turns off.</p></li><li><p>Connect the wireless controller to the host. Press the <strong>START</strong> button, and the buzzers on both robot cars will beep once.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Gently pushing the joysticks in any direction will allow the robot to move at low speed.</strong></p></div><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Button / Stick</strong></th><th style="text-align:center;"><strong>Function</strong></th><th style="text-align:center;"><strong>Description</strong></th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">Stop and reset the robot.</td><td style="text-align:center;">Press</td></tr><tr><td style="text-align:center;">Left Joystick Up</td><td style="text-align:center;">Move forward.</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Left Joystick Down</td><td style="text-align:center;">Move backward.</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Left Joystick Left</td><td style="text-align:center;">Turn left for Mecanum chassis only.</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Left Joystick Right</td><td style="text-align:center;">Turn right for Mecanum chassis only.</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Right Joystick Left</td><td style="text-align:center;">Turn left, controlling Tank chassis and Ackerman chassis front wheels.</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Right Joystick Right</td><td style="text-align:center;">Turn right, controlling Tank chassis and Ackerman chassis front wheels.</td><td style="text-align:center;">Push</td></tr></tbody></table>',94)])])}const B=i(z,[["render",N]]);export{j as __pageData,B as default};
